/**
 * Error codes returned by the plugin.
 * @since 8.3.x
 */
export type SocialLoginErrorCode = 'USER_CANCELLED';

/**
 * Errors thrown by SocialLogin methods.
 *
 * When a user dismisses or cancels the provider UI (popup closed, system dialog cancelled, access denied, etc.),
 * the plugin rejects with `code === 'USER_CANCELLED'` so the caller can distinguish user intent from real failures.
 * Other errors may omit the code or use provider-specific values.
 */
export interface SocialLoginError extends Error {
  code?: SocialLoginErrorCode | string;
}

export interface SocialLoginPlugin {
  /**
   * Initialize the plugin
   * @description initialize the plugin with the required options
   */
  initialize(options: InitializeOptions): Promise<void>;
  /**
   * Login with the selected provider
   * @description login with the selected provider
   *
   * On user dismissal/cancellation, the Promise is rejected with `code === 'USER_CANCELLED'` (see `SocialLoginError`).
   */
  login<T extends LoginOptions['provider']>(
    options: Extract<LoginOptions, { provider: T }>,
  ): Promise<{ provider: T; result: ProviderResponseMap[T] }>;
  /**
   * Logout
   * @description Logout the user from the specified provider
   *
   * **Google Offline Mode Limitation:**
   * This method is NOT supported when Google is initialized with `mode: 'offline'`.
   * It will reject with error: "logout is not implemented when using offline mode"
   *
   * **Google Restore Credentials (Android):**
   * When logging out from Google, the plugin also clears any stored Restore Credential
   * (`google#clearRestoreCredential`) in addition to Credential Manager sign-in state.
   *
   * **Apple cached name (iOS):**
   * The plugin keeps the name Apple returns only on the first authorization, and logging out
   * keeps it. Pass `clearCachedUserInfo: true` to remove it too, for example on account deletion.
   *
   * @throws Error if Google provider is in offline mode
   */
  logout(options: {
    provider: 'apple' | 'google' | 'facebook' | 'twitter' | 'telegram' | 'linkedin' | 'tiktok' | 'oauth2';
    providerId?: string;
    /**
     * Apple on iOS: also remove the first and family name the plugin keeps on the device. Apple
     * returns the name only on the first authorization, so the plugin caches it to fill `givenName`
     * and `familyName` on later logins. Pass `true` when the user deletes their account, or should
     * otherwise leave no trace on the device. The name is removed even if no Apple session is held.
     * Ignored by other providers and platforms.
     * @default false
     */
    clearCachedUserInfo?: boolean;
  }): Promise<void>;
  /**
   * IsLoggedIn
   * @description Check if the user is currently logged in with the specified provider
   *
   * **Google Offline Mode Limitation:**
   * This method is NOT supported when Google is initialized with `mode: 'offline'`.
   * It will reject with error: "isLoggedIn is not implemented when using offline mode"
   *
   * @throws Error if Google provider is in offline mode
   */
  isLoggedIn(options: isLoggedInOptions): Promise<{ isLoggedIn: boolean }>;

  /**
   * Get the current authorization code
   * @description Get the authorization code for server-side authentication
   *
   * **Google Offline Mode Limitation:**
   * This method is NOT supported when Google is initialized with `mode: 'offline'`.
   * It will reject with error: "getAuthorizationCode is not implemented when using offline mode"
   *
   * In offline mode, the authorization code (serverAuthCode) is already returned by the `login()` method.
   *
   * Telegram login does not produce an authorization code; use the `hash` from `login()` and verify it on your backend.
   *
   * @throws Error if Google provider is in offline mode
   */
  getAuthorizationCode(options: AuthorizationCodeOptions): Promise<AuthorizationCode>;
  /**
   * Refresh the access token for the logged-in provider.
   *
   * **Google Android refresh behavior:**
   * On Android, when the saved ID token is still valid and either no access token is stored or Google access
   * token validation succeeds within the timeout, `refresh()` resolves without updating either token. That
   * early return applies regardless of `skipAuthOnlyAuthorizationAfterSignIn`.
   * If validation fails or times out, `refresh()` continues even when a token remains stored; with
   * `skipAuthOnlyAuthorizationAfterSignIn: true` and default OIDC scopes, a successful credential refresh
   * then clears that access token without obtaining a new one.
   *
   * **Google Offline Mode Limitation:**
   * This method is NOT supported when Google is initialized with `mode: 'offline'`.
   * Offline mode only returns `serverAuthCode` for backend token exchange, so token refresh must happen on your backend.
   * The plugin logs and rejects with a message explaining that you should send `serverAuthCode` to your backend,
   * refresh the Google tokens there, or switch to `mode: 'online'` for client-side refresh.
   *
   * **Google Android `skipAuthOnlyAuthorizationAfterSignIn`:**
   * When initialize sets `google.skipAuthOnlyAuthorizationAfterSignIn: true` and only default OIDC scopes are
   * requested, a refresh that runs past the early return skips `AuthorizationClient.authorize()`, updates the
   * saved `idToken`, and clears any saved access token; no new access token is obtained. Enabling the option
   * does not clear a stored access token while the early return applies (validation succeeded or no token
   * stored). With default `false`, refresh still skips authorize on the early return when no access token is
   * stored but the ID token is valid.
   *
   * **Google Web Limitation:**
   * On Web, Google `refresh()` is not implemented, even when using `mode: 'online'`.
   * Call `login()` again on Web to obtain a fresh token instead.
   *
   * @throws Error if Google provider is in offline mode, or on Web where Google `refresh()` is not implemented
   */
  refresh(options: LoginOptions): Promise<void>;

  /**
   * OAuth2 refresh-token helper (feature parity with Capawesome OAuth).
   *
   * Scope:
   * - Applies to the built-in `oauth2` provider and the LinkedIn and TikTok convenience wrappers.
   * - Requires a token endpoint (either `accessTokenEndpoint`/`tokenEndpoint` or `issuerUrl` discovery).
   *
   * Security note:
   * - This does not validate JWT signatures. It only exchanges/refreshes tokens.
   *
   * If `refreshToken` is omitted, the plugin will attempt to use the stored refresh token (if available).
   */
  refreshToken(options: RefreshTokenOptions): Promise<OAuth2LoginResponse>;

  /**
   * Web-only: handle the OAuth redirect callback and return the parsed result.
   *
   * Notes:
   * - This is only meaningful on Web. iOS/Android implementations will reject.
   * - Intended for redirect-based flows (e.g. `oauth2` with `flow: 'redirect'`) where the page navigates away.
   * - LinkedIn convenience logins (`provider: 'linkedin'`, `flow: 'redirect'`) return `provider: 'linkedin'`.
   *   The same app used as `oauth2` with `providerId: 'linkedin'` keeps `provider: 'oauth2'`.
   */
  handleRedirectCallback(): Promise<LoginResult | null>;

  /**
   * Decode a JWT (typically an OIDC ID token) into its claims.
   *
   * Notes:
   * - Accepts both `idToken` and `token` to match common naming (Capawesome uses `token`).
   * - This does not validate the signature or issuer/audience. It only base64url-decodes the payload.
   *
   * **`email_verified` semantics by provider (for account linking):**
   * - **Google** — ID token includes `email_verified` (boolean). When `true`, Google attests
   *   the user controls that email. Verify the JWT on your backend before trusting it.
   * - **Apple** — ID token includes `email_verified` (boolean). When `true`, Apple attests
   *   the user controls that email (including private relay). Verify the JWT on your backend.
   * - **Meta (Facebook)** — Limited Login OIDC tokens may include `email` but **do not**
   *   include `email_verified`. The presence of `email` is not the same guarantee as
   *   `email_verified: true` from Google or Apple. Do not link accounts by email across
   *   providers using Meta claims alone; perform your own email verification if needed.
   */
  decodeIdToken(options: { idToken?: string; token?: string }): Promise<{ claims: Record<string, any> }>;

  /**
   * Convert an access token expiration timestamp (milliseconds since epoch) to an ISO date string.
   *
   * This is a pure helper (feature parity with Capawesome OAuth) and does not depend on provider state.
   */
  getAccessTokenExpirationDate(options: {
    /**
     * Access token expiration date in milliseconds since epoch.
     * Typically: `Date.now() + expiresInSeconds * 1000`.
     */
    accessTokenExpirationDate: number;
  }): Promise<{ date: string }>;

  /**
   * Check if an access token is available (non-empty).
   *
   * This is a pure helper (feature parity with Capawesome OAuth) and does not depend on provider state.
   */
  isAccessTokenAvailable(options: { accessToken: string | null }): Promise<{ isAvailable: boolean }>;

  /**
   * Check if an access token is expired.
   *
   * This is a pure helper (feature parity with Capawesome OAuth) and does not depend on provider state.
   */
  isAccessTokenExpired(options: { accessTokenExpirationDate: number }): Promise<{ isExpired: boolean }>;

  /**
   * Check if a refresh token is available (non-empty).
   *
   * This is a pure helper (feature parity with Capawesome OAuth) and does not depend on provider state.
   */
  isRefreshTokenAvailable(options: { refreshToken: string | null }): Promise<{ isAvailable: boolean }>;

  /**
   * Execute provider-specific calls
   * @description Execute a provider-specific functionality
   */
  providerSpecificCall<T extends ProviderSpecificCall>(options: {
    call: T;
    options: ProviderSpecificCallOptionsMap[T];
  }): Promise<ProviderSpecificCallResponseMap[T]>;

  /**
   * Get the native Capacitor plugin version
   *
   * @returns {Promise<{ id: string }>} an Promise with version for this device
   * @throws An error if the something went wrong
   */
  getPluginVersion(): Promise<{ version: string }>;

  /**
   * Opens a secured window for OAuth2 authentication.
   * For web, you should have the code in the redirected page to use a broadcast channel to send the redirected url to the app
   * Something like:
   * ```html
   * <html>
   * <head></head>
   * <body>
   * <script>
   *   const searchParams = new URLSearchParams(location.search)
   *   if (searchParams.has("code")) {
   *     new BroadcastChannel("my-channel-name").postMessage(location.href);
   *     window.close();
   *   }
   * </script>
   * </body>
   * </html>
   * ```
   * For mobile, you should have a redirect uri that opens the app, something like: `myapp://oauth_callback/`
   * And make sure to register it in the app's info.plist:
   * ```xml
   * <key>CFBundleURLTypes</key>
   * <array>
   *    <dict>
   *       <key>CFBundleURLSchemes</key>
   *       <array>
   *          <string>myapp</string>
   *       </array>
   *    </dict>
   * </array>
   * ```
   * And in the AndroidManifest.xml file:
   * ```xml
   * <activity>
   *    <intent-filter>
   *       <action android:name="android.intent.action.VIEW" />
   *       <category android:name="android.intent.category.DEFAULT" />
   *       <category android:name="android.intent.category.BROWSABLE" />
   *       <data android:host="oauth_callback" android:scheme="myapp" />
   *    </intent-filter>
   * </activity>
   * ```
   * @param options - the options for the openSecureWindow call
   */
  openSecureWindow(options: OpenSecureWindowOptions): Promise<OpenSecureWindowResponse>;

  /**
   * Opens a system auth session for generic OAuth/OIDC or enterprise SSO.
   *
   * Use this when you build the authorize URL yourself (or your IdP SDK returns one) and only need
   * the plugin to run the secure browser flow and return the redirect callback URL. Exchange the
   * authorization code or tokens on your backend or with your own client logic.
   *
   * **iOS/Android:** system browser session (`ASWebAuthenticationSession` / Chrome Custom Tabs).
   * **Web:** popup window plus `BroadcastChannel` (not a native browser session).
   *
   * On user cancel or dismiss, the Promise rejects with `code === 'USER_CANCELLED'`.
   *
   * @param options - auth session options
   */
  openAuthSession(options: OpenAuthSessionOptions): Promise<OpenAuthSessionResult>;
}
